#include <expected>
#include <string>
#include <cassert>
#include <type_traits>
#include <utility>

int main() {
    std::expected<int, std::string> value{2};
    value.emplace(7);
    assert(*value == 7);
    std::unexpect_t tag = std::unexpect;
    std::expected<int, std::string> failure{tag, "invalid"};
    assert(failure.error_or("fallback") == "invalid");
    value = failure;
    try {
        (void)value.value();
        assert(false);
    } catch (const std::bad_expected_access<std::string> &e) {
        assert(e.error() == "invalid");
    }
}
